const SudokuBoard = props => {
  const { board, solution, showSolution, onCellChange } = props;
  return (
    <div className="cell">
        <input
          type="text"
          pattern="\d*"
          novalidate=""
          id={`input-${i}`}
          value={showSolution ? solution[i] : cell}
          maxlength="1"
          onChange={() => onCellChange(i, cell)}
        />
      </div>
  );
};

